frappe.query_reports["SLA - Ticket Details"] = {
    filters: [
        { fieldname: "from_date", label: __("From Date"), fieldtype: "Date", reqd: 1,
          default: frappe.datetime.add_months(frappe.datetime.get_today(), -1) },
        { fieldname: "to_date", label: __("To Date"), fieldtype: "Date", reqd: 1,
          default: frappe.datetime.get_today() },
        { fieldname: "status", label: __("Status"), fieldtype: "Link", options: "HD Ticket Status" },
        { fieldname: "agent_group", label: __("Team"), fieldtype: "Link", options: "HD Team" },
        { fieldname: "custom_agency", label: __("Agency"), fieldtype: "Link", options: "Sabre Agency" },
        { fieldname: "assigned_to", label: __("Assigned To"), fieldtype: "Link", options: "User" },
        { fieldname: "channel", label: __("Channel"), fieldtype: "Select",
          options: "\nPhone Call\nEmail\nManual" },
        { fieldname: "sla_status", label: __("SLA Status"), fieldtype: "Select",
          options: "\nFirst Response Due\nResolution Due\nFailed\nFulfilled\nPaused" },
    ],
    formatter: function (value, row, column, data, default_formatter) {
        value = default_formatter(value, row, column, data);
        const colors = { "Met": "green", "Breached": "red", "Pending": "orange", "Paused": "gray",
                         "Fulfilled": "green", "Failed": "red" };
        if (["response_sla", "resolution_sla", "sla_status"].includes(column.fieldname) && data) {
            const raw = data[column.fieldname];
            if (colors[raw]) {
                value = `<span style="color:${colors[raw]}; font-weight:bold">${value}</span>`;
            }
        }
        if (column.fieldname === "feedback_percent" && data && data.feedback_percent) {
            const p = data.feedback_percent;
            const color = p >= 80 ? "green" : p >= 50 ? "orange" : "red";
            value = `<span style="color:${color}; font-weight:bold">${p}%</span>`;
        }
        return value;
    },
};
